sys_ui_action.client_script_v2:
function onClick(g_form) {
    var taskType = g_form.getValue('task_type');
    if (taskType == "Exception Task" || taskType == "Repair Maker" || taskType == "Repair Checker 1" || taskType == "Repair Checker 2") {
        var readAccessUrl = g_form.getValue('url'); // Always the read access URL
        var assignedTo = g_form.getValue('assigned_to'); // sys_id of assigned user
        var userSysId = g_user.userID;
        var urlToOpen = "";

        if (assignedTo && assignedTo === userSysId) {
            // User is assigned: convert to write access URL
            urlToOpen = readAccessUrl.replace('/readonly/', '/');
        } else {
            // User is not assigned: use read access URL
            urlToOpen = readAccessUrl;
        }

        if (urlToOpen) {
            // g_navigation.openPopup(urlToOpen);
            top.window.open(urlToOpen, "_blank");
        }
    } else {
        var url = g_form.getValue('url'); // MSSTREASURY-153: Restructured to use states and single url field,MSSTRESURY-171
        //MSSTRESURY-192: Appending Task Sys id as a parameter to SWB url
        var taskSysId = g_form.getUniqueValue(); // Get the sys_id of the current task record

        if (url) {
            // Append the task_sys_id as a query parameter to the URL
            url += (url.includes('?') ? '&' : '?') + 'task_sys_id=' + encodeURIComponent(taskSysId);
            // g_navigation.openPopup(url);
            top.window.open(url, "_blank");
        }
    }
}

sys_ui_action.script:
function openWindow() {


    var taskType = g_form.getValue('task_type');
    if (taskType == "Exception Task" || taskType == "Repair Maker" ||  taskType == "Repair Checker 1" || taskType == "Repair Checker 2") {
        var readAccessUrl = g_form.getValue('url'); // Always the read access URL
        var assignedTo = g_form.getValue('assigned_to'); // sys_id of assigned user
        var userSysId = g_user.userID;
        var urlToOpen = "";

        if (assignedTo && assignedTo === userSysId) {
            // User is assigned: convert to write access URL
            urlToOpen = readAccessUrl.replace('/readonly/', '/');
        } else {
            // User is not assigned: use read access URL
            urlToOpen = readAccessUrl;
        }

        if (urlToOpen) {
            g_navigation.openPopup(urlToOpen);
        }
    } else {
        var url = g_form.getValue('url'); // MSSTREASURY-153: Restructured to use states and single url field,MSSTRESURY-171
        //MSSTRESURY-192: Appending Task Sys id as a parameter to SWB url
        var taskSysId = g_form.getUniqueValue(); // Get the sys_id of the current task record

        if (url) {
            // Append the task_sys_id as a query parameter to the URL
            url += (url.includes('?') ? '&' : '?') + 'task_sys_id=' + encodeURIComponent(taskSysId);
            g_navigation.openPopup(url);
        }
    }

}
